// Import of plans generated by the previous planner (generateModel output, or a saved
// "mizan-handasi-project" file) into a drawing document of the studio.
//
// Everything goes through applyCommand(), so the result is an ordinary drawing: the walls
// are real walls, the rooms are derived from them and named by labels, and the user can edit
// it with every tool. Pure: no DOM, no storage, nothing is uploaded.
//
// Legacy frame (same as the studio): x east, y north, metres. Walls are centre-lines with a
// thickness `t`; room / corridor rectangles are the clear (inside) areas; an opening sits on a
// wall at `pos` (0..1 of the wall length, centre of the opening).
import { createDoc, applyCommand, validateDoc, DrawError } from './doc.mjs';
import { isRoomType, ROOM_TYPES } from './catalog.mjs';
import { analyzeWalls } from './topology.mjs';
import { pointInPolygon, closestOnSegment, NODE_TOL } from './geom.mjs';

export const LEGACY_PROJECT_SCHEMA = 'mizan-handasi-project';
const LEVEL = 'L1';
const ENTRIES = ['s', 'n', 'e', 'w'];
const finite = (...v) => v.every(x => typeof x === 'number' && Number.isFinite(x));
const fail = (code, message) => { throw new DrawError(code, message); };
const round3 = v => Math.round(v * 1000) / 1000;

const isRect = r => r && typeof r === 'object' && finite(r.x, r.y, r.w, r.h) && r.w > 0 && r.h > 0;
const isWall = w => w && typeof w === 'object' && finite(w.x1, w.y1, w.x2, w.y2);

/** Shape test for a legacy model (contract versions 1 and 2). */
export function isLegacyModel(m) {
  return !!m && typeof m === 'object' && !Array.isArray(m) && Array.isArray(m.rooms) && Array.isArray(m.walls) && Array.isArray(m.openings)
    && m.walls.length > 0 && m.rooms.some(isRect) && m.walls.some(isWall);
}

const modelSummary = m => ({
  rooms: (m.rooms || []).length, walls: (m.walls || []).length, openings: (m.openings || []).length,
  width: finite(m.plot?.width) ? m.plot.width : null, length: finite(m.plot?.length) ? m.plot.length : null,
});
const plotTitle = m => { const s = modelSummary(m); return s.width && s.length ? `مخطط مستورد ${s.width}×${s.length} م` : 'مخطط مستورد'; };

/**
 * Every legacy plan found in a parsed (or raw text) file:
 *   - a saved project (`schema: "mizan-handasi-project"`): main design, alternatives, previous versions;
 *   - a bare model, or `{ model }`.
 * A saved design that only kept its recipe (no embedded geometry) is regenerated with
 * `generate(recipe)` when that hook is given; otherwise it is reported in `skipped`.
 * Returns { candidates: [{ id, label, model, summary }], skipped: [string] }.
 */
export function findLegacyModels(input, { generate = null } = {}) {
  let raw = input;
  if (typeof input === 'string') { try { raw = JSON.parse(input); } catch { fail('BAD_JSON', 'الملف ليس JSON صالحًا.'); } }
  const candidates = [], skipped = [];
  const add = (id, label, model) => candidates.push({ id, label, model, summary: modelSummary(model) });
  const fromRecipe = (recipe, id, label) => {
    if (!recipe || typeof recipe !== 'object') return;
    if (isLegacyModel(recipe.embedded)) { add(id, label, recipe.embedded); return; }
    if (generate && recipe.plot && recipe.rooms) {
      try { const m = generate(recipe); if (isLegacyModel(m)) { add(id, label, m); return; } } catch (e) { skipped.push(`${label}: تعذّر توليد المخطط من وصفه المحفوظ (${e?.message || 'خطأ'})`); return; }
    }
    skipped.push(`${label}: لا يحتوي هندسة محفوظة.`);
  };
  if (raw && typeof raw === 'object' && raw.schema === LEGACY_PROJECT_SCHEMA) {
    fromRecipe(raw.design, 'design', 'المخطط الأساسي');
    (Array.isArray(raw.alternatives) ? raw.alternatives : []).forEach((r, i) => fromRecipe(r, 'alt' + i, `البديل ${i + 1}`));
    (Array.isArray(raw.history) ? raw.history : []).forEach((h, i) => fromRecipe(h?.design, 'hist' + i, `نسخة سابقة ${i + 1}`));
  } else if (isLegacyModel(raw)) add('model', 'المخطط', raw);
  else if (isLegacyModel(raw?.model)) add('model', 'المخطط', raw.model);
  return { candidates, skipped };
}

/**
 * The legacy planner ends interior walls inside the thickness of the wall they meet (a few centimetres
 * short of its centre-line), so the studio, which joins walls at their centre-lines, sees loose ends and
 * no closed rooms. Every free end that lies within the body of another wall is moved (along its own
 * direction) onto that wall's centre-line. Pure; returns the walls with their moved ends.
 */
export function joinWallEnds(walls) {
  const list = walls.filter(isWall).map(w => ({ src: w, a: { x: w.x1, y: w.y1 }, b: { x: w.x2, y: w.y2 }, t: finite(w.t) && w.t > 0 ? w.t : .2, shiftA: 0 }));
  const touching = (p, self) => list.some(v => v !== self && closestOnSegment(p, v.a, v.b).dist <= NODE_TOL * 2);
  for (const w of list) {
    const len = Math.hypot(w.b.x - w.a.x, w.b.y - w.a.y); if (len < 1e-9) continue;
    const dir = { x: (w.b.x - w.a.x) / len, y: (w.b.y - w.a.y) / len };
    const ends = [{ key: 'a', p: w.a, d: { x: -dir.x, y: -dir.y } }, { key: 'b', p: w.b, d: dir }], moved = {};
    for (const e of ends) {
      if (touching(e.p, w)) continue;
      let best = null;
      for (const v of list) {
        if (v === w) continue;
        const vx = v.b.x - v.a.x, vy = v.b.y - v.a.y, den = e.d.x * vy - e.d.y * vx;
        if (Math.abs(den) < 1e-9) continue; // parallel
        const qx = v.a.x - e.p.x, qy = v.a.y - e.p.y;
        const s = (qx * vy - qy * vx) / den, u = (qx * e.d.y - qy * e.d.x) / den, reach = v.t / 2 + .03, vl = Math.hypot(vx, vy);
        if (Math.abs(s) <= reach && u >= -NODE_TOL / vl && u <= 1 + NODE_TOL / vl && (!best || Math.abs(s) < Math.abs(best.s))) best = { s };
      }
      if (best) moved[e.key] = { p: { x: e.p.x + e.d.x * best.s, y: e.p.y + e.d.y * best.s }, s: best.s };
    }
    // ends are decided against the original geometry; apply them together
    if (moved.a) { w.a = moved.a.p; w.shiftA = moved.a.s; }
    if (moved.b) w.b = moved.b.p;
  }
  return list;
}

/** Same picture of the three legacy opening families the studio knows. */
function openingKind(o) {
  if (o.type === 'window') return o.w >= 1.8 ? 'window2' : 'window';
  if (o.openPlan) return 'arch';
  return o.w >= 1.2 ? 'door2' : 'door';
}

/**
 * Convert a legacy model into a studio document.
 * Returns { doc, report } where report = { rooms, corridors, walls, openings, labels, matched, unmatched[], areaMismatch[], skipped[], warnings[] }.
 * Throws DrawError when the input is not a legacy plan or the result is not a valid drawing.
 */
export function legacyToDoc(model, { title } = {}) {
  if (!isLegacyModel(model)) fail('NOT_LEGACY', 'هذا ليس مخططًا من النظام القديم.');
  const report = { rooms: 0, corridors: 0, courtyards: 0, corridorsMerged: 0, walls: 0, openings: 0, labels: 0, matched: 0, unmatched: [], areaMismatch: [], skipped: [], warnings: [] };
  let doc = createDoc({ title: String(title || plotTitle(model)).slice(0, 120) });
  const run = command => { const r = applyCommand(doc, command); doc = r.doc; return r.ids[0]; };

  // plot, entry side and set-backs
  const W = model.plot?.width, L = model.plot?.length;
  const entry = ENTRIES.includes(model.plot?.entry) ? model.plot.entry : null;
  if (finite(W, L) && W > 0 && L > 0) {
    const sb = model.footprint?.sb, setbacks = sb && ENTRIES.every(k => finite(sb[k])) ? { s: sb.s, n: sb.n, e: sb.e, w: sb.w } : null;
    run({ type: 'set-plot', polygon: [{ x: 0, y: 0 }, { x: W, y: 0 }, { x: W, y: L }, { x: 0, y: L }], ...(setbacks ? { setbacks } : {}), north: 0, entry });
  } else if (entry) run({ type: 'set-plot', entry });

  // storey height follows the drawn walls
  const h = model.walls.find(w => finite(w.h))?.h;
  if (finite(h) && h >= 2 && h <= 8 && Math.abs(h - doc.levels[0].height) > 1e-9) run({ type: 'update', id: LEVEL, patch: { height: h } });

  // walls: legacy centre-lines, with loose ends joined onto the wall they meet
  const joined = joinWallEnds(model.walls), wallIds = new Map(), shift = new Map();
  for (const w of model.walls) if (!isWall(w)) report.skipped.push(`جدار ${w?.id ?? '؟'}: إحداثيات غير صالحة.`);
  for (const j of joined) {
    try {
      const id = run({ type: 'add-wall', level: LEVEL, a: j.a, b: j.b, t: j.t >= .05 && j.t <= 1 ? j.t : undefined });
      wallIds.set(j.src.id, id); shift.set(j.src.id, j.shiftA); report.walls++;
    } catch (e) { report.skipped.push(`جدار ${j.src.id}: ${e.message}`); }
  }

  // openings: `pos` is a fraction of the legacy wall; the studio stores metres from the A end
  // (plus how far the A end was moved when it was joined)
  for (const o of model.openings) {
    const id = wallIds.get(o.wallId), src = model.walls.find(w => w.id === o.wallId);
    if (!id || !src) { report.skipped.push(`فتحة ${o.id ?? '؟'}: جدارها غير موجود.`); continue; }
    if (!finite(o.pos, o.w)) { report.skipped.push(`فتحة ${o.id ?? '؟'}: قياسات غير صالحة.`); continue; }
    const length = Math.hypot(src.x2 - src.x1, src.y2 - src.y1), kind = openingKind(o);
    try {
      run({
        type: 'add-opening', wall: id, kind, at: round3(Math.min(1, Math.max(0, o.pos)) * length + (shift.get(o.wallId) || 0)), w: o.w,
        ...(finite(o.h) ? { h: o.h } : {}), ...(finite(o.sill) ? { sill: o.sill } : {}),
        entry: o.type === 'door' && Array.isArray(o.connects) && o.connects.includes('outside'),
      });
      report.openings++;
    } catch (e) { report.skipped.push(`فتحة ${o.id ?? '؟'}: ${e.message}`); }
  }

  // names: one label at the centre of every room, corridor and courtyard, placed only where it
  // lands inside a closed space; corridors that open into each other are one space and keep one name
  const analysis = analyzeWalls(doc.walls.filter(w => w.level === LEVEL));
  if (analysis.gaps.length) report.warnings.push(`${analysis.gaps.length} فجوة بين الجدران بعد الاستيراد؛ تظهر في المراجعة.`);
  const seeds = [];
  const consider = (r, name, type, group) => {
    if (!isRect(r)) { report.skipped.push(`${group}: مستطيل غير صالح.`); return; }
    const roomType = isRoomType(type) ? type : 'other', seed = { x: round3(r.x + r.w / 2), y: round3(r.y + r.h / 2) };
    seeds.push({ name: String(name || ROOM_TYPES[roomType].ar).slice(0, 60), roomType, seed, area: r.w * r.h, group, space: analysis.spaces.find(sp => sp.net && pointInPolygon(seed, sp.net)) || null });
  };
  for (const r of model.rooms) consider(r, r.name, r.type, 'rooms');
  for (const c of model.corridors || []) consider(c, c.name || 'ممر', 'corridor', 'corridors');
  for (const c of model.courtyards || []) consider(c, c.name || 'فناء داخلي', 'courtyard', 'courtyards');
  const bySpace = new Map();
  for (const s of seeds) if (s.space) { if (!bySpace.has(s.space.id)) bySpace.set(s.space.id, []); bySpace.get(s.space.id).push(s); }
  for (const s of seeds) {
    if (!s.space) { report.unmatched.push(s.name); continue; }
    const mates = bySpace.get(s.space.id), corridorsOnly = mates.every(m => m.roomType === 'corridor');
    if (corridorsOnly && mates.some(m => m !== s && m.area > s.area)) { report.corridorsMerged = (report.corridorsMerged || 0) + 1; continue; }
    if (!corridorsOnly && mates.indexOf(s) > 0) report.warnings.push(`«${s.name}» و«${mates[0].name}» داخل فراغ واحد.`);
    run({ type: 'add-label', level: LEVEL, name: s.name, roomType: s.roomType, seed: s.seed });
    report.labels++; report.matched++; report[s.group]++;
    if (Math.abs(s.space.area - s.area) > Math.max(.05, s.area * .03) && !(corridorsOnly && mates.length > 1)) report.areaMismatch.push({ name: s.name, legacy: Math.round(s.area * 100) / 100, studio: Math.round(s.space.area * 100) / 100 });
  }
  if ((model.reserves || []).length) report.warnings.push(`${model.reserves.length} مساحة غير موزّعة لم تُستورد كغرف.`);
  if ((model.plot?.floors || 1) > 1) report.warnings.push('المخطط القديم يرسم الدور الأرضي فقط؛ أُضيف دور واحد.');

  const errors = validateDoc(doc).filter(i => i.severity === 'error');
  if (errors.length) fail('INVALID_DOC', 'المخطط المستورد غير صالح: ' + errors.slice(0, 3).map(e => e.message).join('، '));
  return { doc, report };
}

export default { LEGACY_PROJECT_SCHEMA, isLegacyModel, findLegacyModels, legacyToDoc, joinWallEnds };
